-- Layer rules for Rofi
hl.layer_rule({
	match = { namespace = "rofi" },
	blur = true,
	ignore_alpha = 0.4,
	animation = "popin 90%",
	dim_around = true,
})

-- Layer rules for Swaync Control Center
hl.layer_rule({
	match = { namespace = "swaync-control-center" },
	blur = true,
	ignore_alpha = 0.4,
	animation = "slide right",
	dim_around = true,
})

-- Layer rules for Swaync notif window
hl.layer_rule({
	match = { namespace = "swaync-notification-window" },
	blur = true,
	ignore_alpha = 0.4,
	animation = "slide right",
})

hl.layer_rule({
	match = { namespace = "swayosd" },
	blur = true,
	ignore_alpha = 0.4,
	animation = "fade",
})

-- Fix transparent/blurred Java popup for SKLauncher
hl.window_rule({
	match = { class = "^(SKLauncher)$" },
	opaque = true,
	no_blur = true,
})

-- Fallback check for alternative sklauncher string patterns
hl.window_rule({
	match = { class = "^(sklauncher|-)$" },
	opaque = true,
	no_blur = true,
})

-- Fix transparent/blurred Tauri popup for Asyar
hl.window_rule({
	match = { class = "^(asyar)$" },
	opaque = true,
	no_blur = true,
})
